export const hasSourceControls=s=>/[\u0000-\u0008\u000b\u000c\u000e-\u001f\ue000-\uf8ff]/.test(s);
export function restoreText(projected,changes){
 let result=projected;
 for(const c of [...changes].reverse()){
  assert.equal(result.slice(c.outputOffset,c.outputOffset+c.after.length),c.after);
  result=result.slice(0,c.outputOffset)+c.before+result.slice(c.outputOffset+c.after.length);
 }return result;
}
